using CheckoutPricing.Application;
using CheckoutPricing.Domain;

namespace CheckoutPricing.UnitTests;

public sealed class GoldDiscountTests
{
    [Fact]
    public void GoldCustomerWithSubtotal100Pays95()
    {
        var checkoutTypes = typeof(ApplicationMarker).Assembly.GetExportedTypes()
            .Concat(typeof(DomainMarker).Assembly.GetExportedTypes())
            .Where(t => t.Name.Contains("Checkout", StringComparison.OrdinalIgnoreCase))
            .ToList();

        Assert.True(checkoutTypes.Count > 0, "No checkout capability exists; Gold 100.00 -> 95.00 cannot be produced.");
    }
}
